window.CODE_INDEX = {"classes":{"AdvancedSearchDialog":{"appearsIn":[["search","h-widgets","Screen \u00b7 component composition"]],"code":"export function AdvancedSearchDialog({\n  disabled,\n  q,\n  filters,\n  onSubmit,\n}: {\n  disabled: boolean\n  q: string\n  filters: SearchFilters\n  onSubmit: (q: string, filters: SearchFilters) => void\n}) {\n  const ax = useAnalytics()\n  const {t: l} = useLingui()\n  const control = Dialog.useDialogControl()\n  const filtersActive = hasActiveFilters(filters)\n  const stateKey = useMemo(\n    () =>\n      JSON.stringify([q, ...FILTER_PARAM_KEYS.map(key => filters[key] ?? '')]),\n    [q, filters],\n  )\n\n  return (\n    <>\n      <View style={[a.relative]}>\n        <Button\n          disabled={disabled}\n          label={l`Open advanced search options`}\n          size=\"small\"\n          color={filtersActive ? 'primary_subtle' : 'secondary'}\n          style={native([a.py_sm, a.px_sm])}\n          onPress={() => {\n            ax.metric('search:advanced:press', {\n              filterCount: countActiveFilters(filters),\n            })\n            control.open()\n          }}>\n          <ButtonIcon icon={SettingsSliderIcon} />\n          <ButtonText>\n            <Trans context=\"search\">Filters</Trans>\n          </ButtonText>\n        </Button>\n      </View>\n\n      <Dialog.Outer control={control} nativeOptions={{preventExpansion: true}}>\n        <Dialog.Handle />\n        <DialogInner\n          key={stateKey}\n          control={control}\n          q={q}\n          filters={filters}\n          onSubmit={onSubmit}\n        />\n      </Dialog.Outer>\n    </>\n  )\n}","file":"src/screens/Search/components/AdvancedSearchDialog/index.tsx","kind":"component","line":40,"members":{"ax":[51,51],"control":[53,53],"disabled":[40,50],"filters":[40,50],"onSubmit":[40,50],"q":[40,50],"stateKey":[55,59]},"supers":[]},"AutocompleteResults":{"appearsIn":[["search","h-widgets","Screen \u00b7 component composition"]],"code":"let AutocompleteResults = ({\n  items,\n  isFetching,\n  searchText,\n  onSubmit,\n  onResultPress,\n  onProfileClick,\n}: {\n  items: AutocompleteItem[]\n  isFetching: boolean\n  searchText: string\n  onSubmit: () => void\n  onResultPress: () => void\n  onProfileClick: (profile: bsky.profile.AnyProfileView) => void\n}): React.ReactNode => {\n  const ax = useAnalytics()\n  const {t: l} = useLingui()\n  const moderationOpts = useModerationOpts()\n\n  return (\n    <>\n      {(isFetching && !items.length) || !moderationOpts ? (\n        <Layout.Content>\n          <View style={[a.py_xl, a.align_center]}>\n            <Loader size=\"xl\" />\n          </View>\n        </Layout.Content>\n      ) : (\n        <Layout.Content\n          keyboardShouldPersistTaps=\"handled\"\n          keyboardDismissMode=\"on-drag\">\n          <SearchLinkCard\n            label={l`Search for \u201c${searchText}\u201d`}\n            onPress={native(onSubmit)}\n            to={\n              IS_NATIVE\n                ? undefined\n                : `/search?q=${encodeURIComponent(searchText)}`\n            }\n            style={a.border_b}\n          />\n          {items.map((item, index) => {\n            if (item.type !== 'profile') return null\n            return (\n              <SearchProfileCard\n                key={item.key}\n                profile={item.profile}\n                moderationOpts={moderationOpts}\n                onPress={() => {\n                  ax.metric('search:autocomplete:press', {\n                    profileDid: item.profile.did,\n                    position: index,\n                  })\n                  onProfileClick(item.profile)\n                  onResultPress()\n                }}\n              />\n            )\n          })}\n          <View style={{height: 200}} />\n        </Layout.Content>\n      )}\n    </>\n  )\n}","file":"src/screens/Search/components/AutocompleteResults.tsx","kind":"component","line":17,"members":{"ax":[32,32],"isFetching":[17,31],"items":[17,31],"moderationOpts":[34,34],"onProfileClick":[17,31],"onResultPress":[17,31],"onSubmit":[17,31],"searchText":[17,31]},"supers":[]},"Explore":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"]],"code":"export function Explore({\n  focusSearchInput,\n}: {\n  focusSearchInput: (tab: 'user' | 'profile' | 'feed') => void\n  headerHeight: number\n}) {\n  const ax = useAnalytics()\n  const {t: l} = useLingui()\n  const t = useTheme()\n  const {data: preferences, error: preferencesError} = usePreferencesQuery()\n  const moderationOpts = useModerationOpts()\n  const [selectedInterest, setSelectedInterest] = useState<string | null>(null)\n\n  /*\n   * Begin special language handling\n   */\n  const {contentLanguages} = useLanguagePrefs()\n  const useFullExperience = useMemo(() => {\n    if (contentLanguages.length === 0) return true\n    return bcp47Match.basicFilter('en', contentLanguages).length > 0\n  }, [contentLanguages])\n  const personalizedInterests = preferences?.interests?.tags\n  const interestsDisplayNames = useInterestsDisplayNames()\n  const interests = Object.keys(interestsDisplayNames)\n    .sort(boostInterests(popularInterests))\n    .sort(boostInterests(personalizedInterests))\n  const {\n    data: suggestedUsers,\n    isLoading: suggestedUsersIsLoading,\n    error: suggestedUsersError,\n    isRefetching: suggestedUsersIsRefetching,\n  } = useGetSuggestedUsersForExploreQuery({\n    category: selectedInterest || (useFullExperience ? null : interests[0]),\n  })\n  /* End special language handling */\n\n  const {\n    data: feeds,\n    hasNextPage: hasNextFeedsPage,\n    isLoading: isLoadingFeeds,\n    isFetchingNextPage: isFetchingNextFeedsPage,\n    error: feedsError,\n    fetchNextPage: fetchNextFeedsPage,\n  } = useGetPopularFeedsQuery({limit: 10, enabled: useFullExperience})\n  const interestsNux = useNux(Nux.ExploreInterestsCard)\n  const showInterestsNux =\n    interestsNux.status === 'ready' && !interestsNux.nux?.completed\n\n  const {\n    data: suggestedSPs,\n    isLoading: isLoadingSuggestedSPs,\n    error: suggestedSPsError,\n    isRefetching: isRefetchingSuggestedSPs,\n  } = useSuggestedStarterPacksQuery({enabled: useFullExperience})\n\n  const isLoadingMoreFeeds = isFetchingNextFeedsPage && !isLoadingFeeds\n  const [hasPressedLoadMoreFeeds, setHasPressedLoadMoreFeeds] = useState(false)\n  const onLoadMoreFeeds = useCallback(async () => {\n    if (isFetchingNextFeedsPage || !hasNextFeedsPage || feedsError) return\n    if (!hasPressedLoadMoreFeeds) {\n      setHasPressedLoadMoreFeeds(true)\n      return\n    }\n    try {\n      await fetchNextFeedsPage()\n    } catch (err) {\n      ax.logger.error('Failed to load more suggested follows', {message: err})\n    }\n  }, [\n    ax,\n    isFetchingNextFeedsPage,\n    hasNextFeedsPage,\n    feedsError,\n    fetchNextFeedsPage,\n    hasPressedLoadMoreFeeds,\n  ])\n\n  const {data: suggestedFeeds, error: suggestedFeedsError} =\n    useGetSuggestedFeedsQuery({\n      enabled: useFullExperience,\n    })\n  const [feedPreviewsEnabled, setFeedPreviewsEnabled] = useState(false)\n  const {\n    data: feedPreviewSlices,\n    query: {\n      isPending: isPendingFeedPreviews,\n      isFetchingNextPage: isFetchingNextPageFeedPreviews,\n      fetchNextPage: fetchNextPageFeedPreviews,\n      hasNextPage: hasNextPageFeedPreviews,\n      error: feedPreviewSlicesError,\n    },\n  } = useFeedPreviews(\n    suggestedFeeds?.feeds.map(({feed}) => feed) ?? [],\n    useFullExperience && feedPreviewsEnabled,\n  )\n\n  const qc = useQueryClient()\n  const [isPTR, setIsPTR] = useState(false)\n  const onPTR = useCallback(async () => {\n    setIsPTR(true)\n    await Promise.all([\n      qc.resetQueries({\n        queryKey: createGetTrendsQueryKey(),\n      }),\n      qc.resetQueries({\n        queryKey: createSuggestedStarterPacksQueryKey(),\n      }),\n      qc.resetQueries({\n        queryKey: [getSuggestedUsersForExploreQueryKeyRoot],\n      }),\n      qc.resetQueries({\n        queryKey: [useActorSearchQueryKeyRoot],\n      }),\n      qc.resetQueries({\n        queryKey: createGetSuggestedFeedsQueryKey(),\n      }),\n    ])\n    setIsPTR(false)\n  }, [qc, setIsPTR])\n\n  const onLoadMoreFeedPreviews = useCallback(async () => {\n    if (\n      isPendingFeedPreviews ||\n      isFetchingNextPageFeedPreviews ||\n      !hasNextPageFeedPreviews ||\n      feedPreviewSlicesError\n    )\n      return\n    try {\n      await fetchNextPageFeedPreviews()\n    } catch (err) {\n      ax.logger.error('Failed to load more feed previews', {message: err})\n    }\n  }, [\n    ax,\n    isPendingFeedPreviews,\n    isFetchingNextPageFeedPreviews,\n    hasNextPageFeedPreviews,\n    feedPreviewSlicesError,\n    fetchNextPageFeedPreviews,\n  ])\n\n  const topBorder = useMemo(\n    () =>\n      ({\n        type: 'topBorder',\n        key: 'top-border',\n      }) as const,\n    [],\n  )\n  const trendingTopicsModule = useMemo(\n    () =>\n      ({\n        type: 'trendingTopics',\n        key: 'trending-topics',\n      }) as const,\n    [],\n  )\n  const suggestedFollowsModule = useMemo(() => {\n    const i: ExploreScreenItems[] = []\n    i.push({\n      type: 'tabbedHeader',\n      key: 'suggested-accounts-header',\n      title: l`Suggested accounts`,\n      icon: Person,\n      iconSize: 'md',\n      searchButton: {\n        label: l`Search for more accounts`,\n        metricsTag: 'suggestedAccounts',\n        tab: 'user',\n      },\n      hideDefaultTab: !useFullExperience,\n    })\n\n    if (suggestedUsersIsLoading || suggestedUsersIsRefetching) {\n      i.push({type: 'profilePlaceholder', key: 'profilePlaceholder'})\n    } else if (suggestedUsersError) {\n      i.push({\n        type: 'error',\n        key: 'suggestedUsersError',\n        message: l`Failed to load suggested follows`,\n        error: cleanError(suggestedUsersError),\n      })\n    } else {\n      if (suggestedUsers !== undefined) {\n        if (suggestedUsers.actors.length > 0 && moderationOpts) {\n          // Currently the responses contain duplicate items.\n          // Needs to be fixed on backend, but let's dedupe to be safe.\n          let seen = new Set()\n          const profileItems: ExploreScreenItems[] = []\n          for (const actor of suggestedUsers.actors) {\n            // checking for following still necessary if search data is used\n            if (!seen.has(actor.did) && !actor.viewer?.following) {\n              seen.add(actor.did)\n              profileItems.push({\n                type: 'profile',\n                key: actor.did,\n                profile: actor,\n                recId: suggestedUsers.recId,\n              })\n            }\n          }\n\n          if (profileItems.length === 0) {\n            i.push({\n              type: 'profileEmpty',\n              key: 'profileEmpty',\n            })\n          } else {\n            if (selectedInterest === null && useFullExperience) {\n              // First \"For You\" tab, only show 5 to keep screen short\n              i.push(...profileItems.slice(0, 5))\n            } else {\n              i.push(...profileItems)\n            }\n          }\n        } else {\n          i.push({\n            type: 'profileEmpty',\n            key: 'profileEmpty',\n          })\n        }\n      } else {\n        i.push({type: 'profilePlaceholder', key: 'profilePlaceholder'})\n      }\n    }\n    return i\n  }, [\n    l,\n    moderationOpts,\n    suggestedUsers,\n    suggestedUsersIsLoading,\n    suggestedUsersIsRefetching,\n    suggestedUsersError,\n    selectedInterest,\n    useFullExperience,\n  ])\n  const suggestedFeedsModule = useMemo(() => {\n    const i: ExploreScreenItems[] = []\n    i.push({\n      type: 'header',\n      key: 'suggested-feeds-header',\n      title: l`Discover feeds`,\n      icon: ListSparkle,\n      iconSize: 'md',\n      searchButton: {\n        label: l`Search for more feeds`,\n        metricsTag: 'suggestedFeeds',\n        tab: 'feed',\n      },\n    })\n\n    if (useFullExperience) {\n      if (suggestedFeeds && preferences) {\n        let seen = new Set()\n        const feedItems: ExploreScreenItems[] = []\n        for (const {feed, position} of suggestedFeeds.feeds) {\n          if (!seen.has(feed.uri)) {\n            seen.add(feed.uri)\n            feedItems.push({\n              type: 'feed',\n              key: feed.uri,\n              feed,\n              recommendation: {\n                recId: suggestedFeeds.recId,\n                position,\n              },\n            })\n          }\n        }\n\n        // feeds errors can occur during pagination, so feeds is truthy\n        if (suggestedFeedsError) {\n          i.push({\n            type: 'error',\n            key: 'suggestedFeedsError',\n            message: l`Failed to load suggested feeds`,\n            error: cleanError(suggestedFeedsError),\n          })\n        } else if (preferencesError) {\n          i.push({\n            type: 'error',\n            key: 'preferencesError',\n            message: l`Failed to load feeds preferences`,\n            error: cleanError(preferencesError),\n          })\n        } else {\n          if (feedItems.length === 0) {\n            i.pop()\n          } else {\n            // This query doesn't follow the limit very well, so the first press of the\n            // load more button just unslices the array back to ~10 items\n            if (!hasPressedLoadMoreFeeds) {\n              i.push(...feedItems.slice(0, 6))\n            } else {\n              i.push(...feedItems)\n            }\n          }\n          if (!hasPressedLoadMoreFeeds) {\n            i.push({\n              type: 'loadMore',\n              key: 'loadMoreFeeds',\n              message: l`Load more suggested feeds`,\n              isLoadingMore: isLoadingMoreFeeds,\n              onLoadMore: onLoadMoreFeeds,\n            })\n          }\n        }\n      } else {\n        if (feedsError) {\n          i.push({\n            type: 'error',\n            key: 'feedsError',\n            message: l`Failed to load feeds`,\n            error: cleanError(feedsError),\n          })\n        } else if (suggestedFeedsError) {\n          i.push({\n            type: 'error',\n            key: 'suggestedFeedsError',\n            message: l`Failed to load suggested feeds`,\n            error: cleanError(suggestedFeedsError),\n          })\n        } else if (preferencesError) {\n          i.push({\n            type: 'error',\n            key: 'preferencesError',\n            message: l`Failed to load feeds preferences`,\n            error: cleanError(preferencesError),\n          })\n        } else {\n          i.push({type: 'feedPlaceholder', key: 'feedPlaceholder'})\n        }\n      }\n    } else {\n      if (feeds && preferences) {\n        // Currently the responses contain duplicate items.\n        // Needs to be fixed on backend, but let's dedupe to be safe.\n        let seen = new Set()\n        const feedItems: ExploreScreenItems[] = []\n        for (const page of feeds.pages) {\n          for (const feed of page.feeds) {\n            if (!seen.has(feed.uri)) {\n              seen.add(feed.uri)\n              feedItems.push({\n                type: 'feed',\n                key: feed.uri,\n                feed,\n              })\n            }\n          }\n        }\n\n        // feeds errors can occur during pagination, so feeds is truthy\n        if (feedsError) {\n          i.push({\n            type: 'error',\n            key: 'feedsError',\n            message: l`Failed to load feeds`,\n            error: cleanError(feedsError),\n          })\n        } else if (suggestedFeedsError) {\n          i.push({\n            type: 'error',\n            key: 'suggestedFeedsError',\n            message: l`Failed to load suggested feeds`,\n            error: cleanError(suggestedFeedsError),\n          })\n        } else if (preferencesError) {\n          i.push({\n            type: 'error',\n            key: 'preferencesError',\n            message: l`Failed to load feeds preferences`,\n            error: cleanError(preferencesError),\n          })\n        } else {\n          if (feedItems.length === 0) {\n            if (!hasNextFeedsPage) {\n              i.pop()\n            }\n          } else {\n            // This query doesn't follow the limit very well, so the first press of the\n            // load more button just unslices the array back to ~10 items\n            if (!hasPressedLoadMoreFeeds) {\n              i.push(...feedItems.slice(0, 3))\n            } else {\n              i.push(...feedItems)\n            }\n          }\n          if (hasNextFeedsPage) {\n            i.push({\n              type: 'loadMore',\n              key: 'loadMoreFeeds',\n              message: l`Load more suggested feeds`,\n              isLoadingMore: isLoadingMoreFeeds,\n              onLoadMore: onLoadMoreFeeds,\n            })\n          }\n        }\n      } else {\n        if (feedsError) {\n          i.push({\n            type: 'error',\n            key: 'feedsError',\n            message: l`Failed to load feeds`,\n            error: cleanError(feedsError),\n          })\n        } else if (suggestedFeedsError) {\n          i.push({\n            type: 'error',\n            key: 'feedsError',\n            message: l`Failed to load suggested feeds`,\n            error: cleanError(suggestedFeedsError),\n          })\n        } else if (preferencesError) {\n          i.push({\n            type: 'error',\n            key: 'preferencesError',\n            message: l`Failed to load feeds preferences`,\n            error: cleanError(preferencesError),\n          })\n        } else {\n          i.push({type: 'feedPlaceholder', key: 'feedPlaceholder'})\n        }\n      }\n    }\n    return i\n  }, [\n    l,\n    ax,\n    useFullExperience,\n    suggestedFeeds,\n    preferences,\n    suggestedFeedsError,\n    preferencesError,\n    feedsError,\n    hasNextFeedsPage,\n    hasPressedLoadMoreFeeds,\n    isLoadingMoreFeeds,\n    onLoadMoreFeeds,\n    feeds,\n  ])\n\n  const suggestedStarterPacksModule = useMemo(() => {\n    const i: ExploreScreenItems[] = []\n    i.push({\n      type: 'header',\n      key: 'suggested-starterPacks-header',\n      title: l`Starter Packs`,\n      icon: StarterPackIcon,\n      iconSize: 'md',\n    })\n\n    if (isLoadingSuggestedSPs || isRefetchingSuggestedSPs) {\n      Array.from({length: 3}).forEach((__, index) =>\n        i.push({\n          type: 'starterPackSkeleton',\n          key: `starterPackSkeleton-${index}`,\n        }),\n      )\n    } else if (suggestedSPsError || !suggestedSPs) {\n      // just get rid of the section\n      i.pop()\n    } else {\n      suggestedSPs.starterPacks.map((s, position) => {\n        i.push({\n          type: 'starterPack',\n          key: s.uri,\n          view: s,\n          recommendation: {\n            recId: suggestedSPs.recId,\n            position,\n          },\n        })\n      })\n    }\n    return i\n  }, [\n    suggestedSPs,\n    l,\n    isLoadingSuggestedSPs,\n    suggestedSPsError,\n    isRefetchingSuggestedSPs,\n  ])\n  const feedPreviewsModule = useMemo(() => {\n    const i: ExploreScreenItems[] = []\n    i.push(...feedPreviewSlices)\n    if (isFetchingNextPageFeedPreviews) {\n      i.push({\n        type: 'preview:loading',\n        key: 'preview-loading-more',\n      })\n    }\n    return i\n  }, [feedPreviewSlices, isFetchingNextPageFeedPreviews])\n\n  const interestsNuxModule = useMemo<ExploreScreenItems[]>(() => {\n    if (!showInterestsNux) return []\n    return [\n      {\n        type: 'interests-card',\n        key: 'interests-card',\n      },\n    ]\n  }, [showInterestsNux])\n\n  const items = useMemo<ExploreScreenItems[]>(() => {\n    const i: ExploreScreenItems[] = []\n\n    // Dynamic module ordering\n\n    i.push(topBorder)\n    i.push(...interestsNuxModule)\n\n    i.push({type: 'liveEventFeedsBanner', key: 'liveEventFeedsBanner'})\n\n    if (useFullExperience) {\n      i.push(trendingTopicsModule)\n      i.push(...suggestedFeedsModule)\n      i.push(...suggestedFollowsModule)\n      i.push(...suggestedStarterPacksModule)\n      i.push(...feedPreviewsModule)\n    } else {\n      i.push(...suggestedFollowsModule)\n    }\n\n    return i\n  }, [\n    topBorder,\n    suggestedFollowsModule,\n    suggestedStarterPacksModule,\n    suggestedFeedsModule,\n    trendingTopicsModule,\n    feedPreviewsModule,\n    interestsNuxModule,\n    useFullExperience,\n  ])\n\n  const renderItem = useCallback(\n    ({item, index}: {item: ExploreScreenItems; index: number}) => {\n      const handleOnPressRetry = () => {\n        void fetchNextPageFeedPreviews()\n      }\n      switch (item.type) {\n        case 'topBorder':\n          return (\n            <View style={[a.w_full, t.atoms.border_contrast_low, a.border_t]} />\n          )\n        case 'header': {\n          return (\n            <ModuleHeader.Container bottomBorder={item.bottomBorder}>\n              <ModuleHeader.Icon icon={item.icon} size={item.iconSize} />\n              <ModuleHeader.TitleText>{item.title}</ModuleHeader.TitleText>\n              {item.searchButton && (\n                <ModuleHeader.SearchButton\n                  {...item.searchButton}\n                  onPress={() =>\n                    focusSearchInput(item.searchButton?.tab || 'user')\n                  }\n                />\n              )}\n            </ModuleHeader.Container>\n          )\n        }\n        case 'tabbedHeader': {\n          return (\n            <View style={[a.pb_md]}>\n              <ModuleHeader.Container style={[a.pb_xs]}>\n                <ModuleHeader.Icon icon={item.icon} size={item.iconSize} />\n                <ModuleHeader.TitleText>{item.title}</ModuleHeader.TitleText>\n                {item.searchButton && (\n                  <ModuleHeader.SearchButton\n                    {...item.searchButton}\n                    onPress={() =>\n                      focusSearchInput(item.searchButton?.tab || 'user')\n                    }\n                  />\n                )}\n              </ModuleHeader.Container>\n              <SuggestedAccountsTabBar\n                selectedInterest={selectedInterest}\n                onSelectInterest={setSelectedInterest}\n                hideDefaultTab={item.hideDefaultTab}\n              />\n            </View>\n          )\n        }\n        case 'trendingTopics': {\n          return <ExploreTrendingTopics />\n        }\n        case 'trendingVideos': {\n          return <ExploreTrendingVideos />\n        }\n        case 'profile': {\n          return (\n            <SuggestedProfileCard\n              profile={item.profile}\n              moderationOpts={moderationOpts!}\n              recId={item.recId}\n              position={index}\n            />\n          )\n        }\n        case 'profileEmpty': {\n          return (\n            <View style={[a.px_lg, a.pb_lg]}>\n              <Admonition>\n                {selectedInterest ? (\n                  <Trans>\n                    No results for \"{interestsDisplayNames[selectedInterest]}\".\n                  </Trans>\n                ) : (\n                  <Trans>No results.</Trans>\n                )}\n              </Admonition>\n            </View>\n          )\n        }\n        case 'feed': {\n          return (\n            <View\n              style={[\n                a.border_t,\n                t.atoms.border_contrast_low,\n                a.px_lg,\n                a.py_lg,\n              ]}>\n              <FeedCard.Default\n                view={item.feed}\n                onPress={() => {\n                  if (!item.recommendation) return\n                  ax.metric('feed:suggestion:press', {\n                    feedUrl: item.feed.uri,\n                    logContext: 'Explore',\n                    recId: item.recommendation.recId,\n                    position: item.recommendation.position,\n                  })\n                }}\n                onSavedFeedChange={action => {\n                  if (!item.recommendation?.recId) return\n                  const payload = {\n                    feedUrl: item.feed.uri,\n                    logContext: 'Explore' as const,\n                    recId: item.recommendation.recId,\n                    position: item.recommendation.position,\n                  }\n                  if (action === 'save') {\n                    ax.metric('feed:save', payload)\n                  } else if (action === 'unsave') {\n                    ax.metric('feed:unsave', payload)\n                  } else if (action === 'pin') {\n                    ax.metric('feed:pin', payload)\n                  } else {\n                    ax.metric('feed:unpin', payload)\n                  }\n                }}\n              />\n            </View>\n          )\n        }\n        case 'starterPack': {\n          return (\n            <View style={[a.px_lg, a.pb_lg]}>\n              <StarterPackCard\n                view={item.view}\n                onPress={() => {\n                  if (!item.recommendation.recId) return\n                  ax.metric('starterPack:suggestion:press', {\n                    logContext: 'Explore',\n                    starterPack: item.view.uri,\n                    recId: item.recommendation.recId,\n                    position: item.recommendation.position,\n                  })\n                }}\n              />\n            </View>\n          )\n        }\n        case 'starterPackSkeleton': {\n          return (\n            <View style={[a.px_lg, a.pb_lg]}>\n              <StarterPackCardSkeleton />\n            </View>\n          )\n        }\n        case 'loadMore': {\n          return (\n            <View style={[a.border_t, t.atoms.border_contrast_low]}>\n              <LoadMore item={item} />\n            </View>\n          )\n        }\n        case 'profilePlaceholder': {\n          return (\n            <>\n              {Array.from({length: 3}).map((__, i) => (\n                <View\n                  style={[\n                    a.px_lg,\n                    a.py_lg,\n                    a.border_t,\n                    t.atoms.border_contrast_low,\n                  ]}\n                  key={i}>\n                  <ProfileCard.Outer>\n                    <ProfileCard.Header>\n                      <ProfileCard.AvatarPlaceholder />\n                      <ProfileCard.NameAndHandlePlaceholder />\n                    </ProfileCard.Header>\n                    <ProfileCard.DescriptionPlaceholder numberOfLines={2} />\n                  </ProfileCard.Outer>\n                </View>\n              ))}\n            </>\n          )\n        }\n        case 'feedPlaceholder': {\n          return <FeedCardListSkeleton />\n        }\n        case 'error':\n        case 'preview:error': {\n          return (\n            <View\n              style={[\n                a.border_t,\n                a.pt_md,\n                a.px_md,\n                t.atoms.border_contrast_low,\n              ]}>\n              <View\n                style={[\n                  a.flex_row,\n                  a.gap_md,\n                  a.p_lg,\n                  a.rounded_sm,\n                  t.atoms.bg_contrast_25,\n                ]}>\n                <CircleInfo size=\"md\" fill={t.palette.negative_400} />\n                <View style={[a.flex_1, a.gap_sm]}>\n                  <Text style={[a.font_semi_bold, a.leading_snug]}>\n                    {item.message}\n                  </Text>\n                  <Text\n                    style={[\n                      a.italic,\n                      a.leading_snug,\n                      t.atoms.text_contrast_medium,\n                    ]}>\n                    {item.error}\n                  </Text>\n                </View>\n              </View>\n            </View>\n          )\n        }\n        // feed previews\n        case 'preview:spacer': {\n          return <View style={[a.w_full, a.pt_4xl]} />\n        }\n        case 'preview:empty': {\n          return null // what should we do here?\n        }\n        case 'preview:loading': {\n          return (\n            <View style={[a.py_2xl, a.flex_1, a.align_center]}>\n              <Loader size=\"lg\" />\n            </View>\n          )\n        }\n        case 'preview:header': {\n          return (\n            <ModuleHeader.Container style={[a.pt_xs]} bottomBorder>\n              {/* Very non-scientific way to avoid small gap on scroll */}\n              <View style={[a.absolute, a.inset_0, t.atoms.bg, {top: -2}]} />\n              <ModuleHeader.FeedLink feed={item.feed}>\n                <ModuleHeader.FeedAvatar feed={item.feed} />\n                <View style={[a.flex_1, a.gap_2xs]}>\n                  <ModuleHeader.TitleText style={[a.text_lg]}>\n                    {item.feed.displayName}\n                  </ModuleHeader.TitleText>\n                  <ModuleHeader.SubtitleText>\n                    <Trans>\n                      By {sanitizeHandle(item.feed.creator.handle, '@')}\n                    </Trans>\n                  </ModuleHeader.SubtitleText>\n                </View>\n              </ModuleHeader.FeedLink>\n              <ModuleHeader.PinButton feed={item.feed} />\n            </ModuleHeader.Container>\n          )\n        }\n        case 'preview:footer': {\n          return (\n            <View\n              style={[\n                a.border_t,\n                t.atoms.border_contrast_low,\n                a.w_full,\n                a.pt_4xl,\n              ]}\n            />\n          )\n        }\n        case 'preview:sliceItem': {\n          const slice = item.slice\n          const indexInSlice = item.indexInSlice\n          const subItem = slice.items[indexInSlice]\n          return (\n            <PostFeedItem\n              post={subItem.post}\n              record={subItem.record}\n              postNumbering={subItem.postNumbering}\n              reason={indexInSlice === 0 ? slice.reason : undefined}\n              feedContext={slice.feedContext}\n              reqId={slice.reqId}\n              moderation={subItem.moderation}\n              parentAuthor={subItem.parentAuthor}\n              showReplyTo={item.showReplyTo}\n              isThreadParent={isThreadParentAt(slice.items, indexInSlice)}\n              isThreadChild={isThreadChildAt(slice.items, indexInSlice)}\n              isThreadLastChild={\n                isThreadChildAt(slice.items, indexInSlice) &&\n                slice.items.length === indexInSlice + 1\n              }\n              isParentBlocked={subItem.isParentBlocked}\n              isParentNotFound={subItem.isParentNotFound}\n              hideTopBorder={item.hideTopBorder}\n              rootPost={slice.items[0].post}\n            />\n          )\n        }\n        case 'preview:sliceViewFullThread': {\n          return <ViewFullThread uri={item.uri} />\n        }\n        case 'preview:loadMoreError': {\n          return (\n            <LoadMoreRetryBtn\n              label={l`There was an issue fetching posts. Tap here to try again.`}\n              onPress={handleOnPressRetry}\n            />\n          )\n        }\n        case 'interests-card': {\n          return <ExploreInterestsCard />\n        }\n        case 'liveEventFeedsBanner': {\n          return <ExploreScreenLiveEventFeedsBanner />\n        }\n      }\n    },\n    [\n      ax,\n      t.atoms.border_contrast_low,\n      t.atoms.bg_contrast_25,\n      t.atoms.text_contrast_medium,\n      t.atoms.bg,\n      t.palette.negative_400,\n      focusSearchInput,\n      selectedInterest,\n      moderationOpts,\n      interestsDisplayNames,\n      useFullExperience,\n      l,\n      fetchNextPageFeedPreviews,\n    ],\n  )\n\n  const stickyHeaderIndices = useMemo(\n    () =>\n      items.reduce(\n        (acc, curr) =>\n          ['topBorder', 'preview:header'].includes(curr.type)\n            ? acc.concat(items.indexOf(curr))\n            : acc,\n        [] as number[],\n      ),\n    [items],\n  )\n\n  // track headers and report module viewability\n  const alreadyReportedRef = useRef<Map<string, string>>(new Map())\n  const seenProfilesRef = useRef<Set<string>>(new Set())\n  const seenFeedsRef = useRef<Set<string>>(new Set())\n  const seenStarterPacksRef = useRef<Set<string>>(new Set())\n  const onItemSeen = useCallback(\n    (item: ExploreScreenItems) => {\n      let module: Metrics['explore:module:seen']['module']\n      if (item.type === 'trendingTopics' || item.type === 'trendingVideos') {\n        module = item.type\n      } else if (item.type === 'profile') {\n        module = 'suggestedAccounts'\n        // Track individual profile seen events\n        if (!seenProfilesRef.current.has(item.profile.did)) {\n          seenProfilesRef.current.add(item.profile.did)\n          const position = suggestedFollowsModule.findIndex(\n            i => i.type === 'profile' && i.profile.did === item.profile.did,\n          )\n          ax.metric('suggestedUser:seen', {\n            logContext: 'Explore',\n            recId: item.recId,\n            position: position !== -1 ? position - 1 : 0, // -1 to account for header\n            suggestedDid: item.profile.did,\n            category: null,\n          })\n        }\n      } else if (item.type === 'feed') {\n        module = 'suggestedFeeds'\n        if (item.recommendation) {\n          const key = `${item.recommendation.recId ?? 'legacy'}:${item.feed.uri}`\n          if (!seenFeedsRef.current.has(key)) {\n            seenFeedsRef.current.add(key)\n            ax.metric('feed:suggestion:seen', {\n              feedUrl: item.feed.uri,\n              logContext: 'Explore',\n              recId: item.recommendation.recId,\n              position: item.recommendation.position,\n            })\n          }\n        }\n      } else if (item.type === 'starterPack') {\n        module = 'suggestedStarterPacks'\n        const key = `${item.recommendation.recId ?? 'legacy'}:${item.view.uri}`\n        if (\n          item.recommendation.recId &&\n          !seenStarterPacksRef.current.has(key)\n        ) {\n          seenStarterPacksRef.current.add(key)\n          ax.metric('starterPack:suggestion:seen', {\n            logContext: 'Explore',\n            starterPack: item.view.uri,\n            recId: item.recommendation.recId,\n            position: item.recommendation.position,\n          })\n        }\n      } else if (item.type === 'preview:sliceItem') {\n        module = `feed:feedgen|${item.feed.uri}`\n      } else {\n        return\n      }\n      if (!alreadyReportedRef.current.has(module)) {\n        alreadyReportedRef.current.set(module, module)\n        ax.metric('explore:module:seen', {module})\n      }\n    },\n    [ax, suggestedFollowsModule],\n  )\n\n  const handleOnEndReached = () => {\n    if (!useFullExperience) return\n    if (!feedPreviewsEnabled) {\n      setFeedPreviewsEnabled(true)\n      return\n    }\n    void onLoadMoreFeedPreviews()\n  }\n\n  const handleOnRefresh = () => {\n    void onPTR()\n  }\n\n  return (\n    <List\n      data={items}\n      renderItem={renderItem}\n      keyExtractor={keyExtractor}\n      desktopFixedHeight\n      contentContainerStyle={{paddingBottom: 100}}\n      keyboardShouldPersistTaps=\"handled\"\n      keyboardDismissMode=\"on-drag\"\n      stickyHeaderIndices={native(stickyHeaderIndices)}\n      viewabilityConfig={viewabilityConfig}\n      onItemSeen={onItemSeen}\n      onEndReached={handleOnEndReached}\n      /**\n       * Default: 2\n       */\n      onEndReachedThreshold={4}\n      /**\n       * Default: 10\n       */\n      initialNumToRender={10}\n      /**\n       * Default: 21\n       */\n      windowSize={platform({android: 11})}\n      /**\n       * Default: 10\n       *\n       * NOTE: This was 1 on Android. Unfortunately this leads to the list totally freaking out\n       * when the sticky headers changed. I made a minimal reproduction and yeah, it's this prop.\n       * Totally fine when the sticky headers are static, but when they're dynamic, it's a mess.\n       *\n       * Repro: https://github.com/mozzius/stickyindices-repro\n       *\n       * I then found doubling this prop on iOS also reduced it freaking out there as well.\n       *\n       * Trades off seeing more blank space due to it having to render more items before it can show anything.\n       * -sfn\n       */\n      maxToRenderPerBatch={platform({android: 10, ios: 20})}\n      /**\n       * Default: 50\n       *\n       * NOTE: This was 25 on Android. However, due to maxToRenderPerBatch being set to 10,\n       * the lower batching period is no longer necessary (?)\n       */\n      updateCellsBatchingPeriod={50}\n      refreshing={isPTR}\n      onRefresh={handleOnRefresh}\n    />\n  )\n}","file":"src/screens/Search/Explore.tsx","kind":"component","line":215,"members":{"alreadyReportedRef":[1095,1095],"ax":[221,221],"feedPreviewsEnabled":[296,296],"feedPreviewsModule":[699,709],"focusSearchInput":[215,220],"handleOnEndReached":[1162,1169],"handleOnRefresh":[1171,1173],"hasPressedLoadMoreFeeds":[271,271],"interestsDisplayNames":[237,237],"interestsNux":[259,259],"interestsNuxModule":[711,719],"isPTR":[312,312],"items":[721,751],"moderationOpts":[225,225],"onItemSeen":[1099,1160],"onLoadMoreFeedPreviews":[335,355],"onLoadMoreFeeds":[272,290],"onPTR":[313,333],"qc":[311,311],"renderItem":[753,1080],"seenFeedsRef":[1097,1097],"seenProfilesRef":[1096,1096],"seenStarterPacksRef":[1098,1098],"selectedInterest":[226,226],"stickyHeaderIndices":[1082,1092],"suggestedFeedsModule":[452,656],"suggestedFollowsModule":[373,451],"suggestedStarterPacksModule":[658,698],"t":[223,223],"topBorder":[357,364],"trendingTopicsModule":[365,372],"useFullExperience":[232,235]},"supers":[]},"SearchAutocompleteInput":{"alsoIn":["src/screens/Search/components/SearchAutocompleteInput/index.native.tsx"],"appearsIn":[["search","h-widgets","Screen \u00b7 component composition"]],"code":"/**\n * Web: typed results float in a Sift dropdown anchored to the search input\n * (matching the desktop nav-bar search). Search history continues to render\n * full-page underneath the input in Shell.tsx, so it is not shown here. See\n * index.native.tsx for the native (inline list) variant.\n */\nexport function SearchAutocompleteInput({\n  fixedParams,\n  onSelectProfile,\n  onSelectSearch,\n  value = '',\n  onFocus,\n  onBlur,\n  onChangeText,\n  ref,\n  ...rest\n}: SearchAutocompleteInputProps) {\n  const [focused, setFocused] = useState(false)\n  /*\n   * Sift dismisses on Escape without blurring the input, so `focused` stays\n   * true. Track that dismissal separately (reset on type or refocus) rather\n   * than clearing `focused`, otherwise the dropdown wouldn't reopen on the next\n   * keystroke while the input is still focused.\n   */\n  const [dismissed, setDismissed] = useState(false)\n  const inputRef = useRef<React.ComponentRef<typeof TextInput>>(null)\n\n  const sift = useSift({\n    offset: a.p_sm.padding,\n    placement: 'bottom',\n  })\n\n  const active = focused && !dismissed\n\n  const {items} = useAutocomplete({\n    type: 'profile',\n    // The dropdown only shows while active, so don't fetch otherwise. This\n    // avoids a typeahead request on mount when arriving with text already\n    // present (e.g. /search?q=foo).\n    query: active ? value : '',\n    showSearchFallback: true,\n  })\n\n  const showDropdown =\n    active && !fixedParams && value.length > 0 && items.length > 0\n\n  function onSelect(item: AutocompleteItem) {\n    if (item.type === 'profile') {\n      const position = items.filter(i => i.type === 'profile').indexOf(item)\n      onSelectProfile?.(item.profile, position)\n    } else if (item.type === 'search') {\n      onSelectSearch?.(item.value)\n    }\n    inputRef.current?.blur()\n  }\n\n  /*\n   * setAnchor goes on the full-width wrapper View so the dropdown matches the\n   * input's container width; the input ref (targetProps.ref) lands on the inner\n   * TextInput for Sift's positioning math, and the remaining combobox a11y\n   * props are spread onto the input.\n   */\n  const {setAnchor} = sift.refs\n  const {ref: inputAnchorRef, ...comboboxProps} = sift.targetProps\n\n  return (\n    <View\n      collapsable={false}\n      ref={setAnchor}\n      /*\n       * Focusing the input reveals the Cancel button alongside it (see\n       * Shell.tsx), which shrinks the anchor after Sift's initial measurement\n       * and leaves the dropdown too wide until the next re-measure. Recompute on\n       * layout (react-native-web backs onLayout with a ResizeObserver) so the\n       * width tracks the anchor through that reflow and window resizes.\n       */\n      onLayout={() => void sift.updatePosition()}>\n      <SearchInput\n        {...rest}\n        {...comboboxProps}\n        ref={mergeRefs([ref, inputAnchorRef, inputRef])}\n        value={value}\n        onChangeText={text => {\n          setDismissed(false)\n          onChangeText?.(text)\n        }}\n        onFocus={e => {\n          setDismissed(false)\n          setFocused(true)\n          onFocus?.(e)\n        }}\n        onBlur={e => {\n          setFocused(false)\n          onBlur?.(e)\n        }}\n      />\n      {showDropdown && (\n        <Autocomplete\n          sift={sift}\n          data={items}\n          onSelect={onSelect}\n          onDismiss={() => setDismissed(true)}\n          fullWidth\n        />\n      )}\n    </View>\n  )\n}","file":"src/screens/Search/components/SearchAutocompleteInput/index.tsx","kind":"component","line":15,"members":{"dismissed":[39,39],"fixedParams":[21,31],"focused":[32,32],"inputRef":[40,40],"onBlur":[21,31],"onChangeText":[21,31],"onFocus":[21,31],"onSelect":[61,69],"onSelectProfile":[21,31],"onSelectSearch":[21,31],"ref":[21,31],"rest":[21,31],"sift":[42,45],"value":[21,31]},"supers":[]},"SearchHistory":{"appearsIn":[["search","h-widgets","Screen \u00b7 component composition"]],"code":"export function SearchHistory({\n  searchHistory,\n  selectedProfiles,\n  onItemClick,\n  onProfileClick,\n  onRemoveItemClick,\n  onRemoveProfileClick,\n  onClearAll,\n}: {\n  searchHistory: string[]\n  selectedProfiles: bsky.profile.AnyProfileView[]\n  onItemClick: (item: string) => void\n  onProfileClick: (profile: bsky.profile.AnyProfileView) => void\n  onRemoveItemClick: (item: string) => void\n  onRemoveProfileClick: (profile: bsky.profile.AnyProfileView) => void\n  onClearAll: () => void\n}) {\n  const ax = useAnalytics()\n  const {t: l} = useLingui()\n  const moderationOpts = useModerationOpts()\n  const clearAllPromptControl = Prompt.usePromptControl()\n\n  const totalCount = searchHistory.length + selectedProfiles.length\n\n  return (\n    <Layout.Content\n      keyboardDismissMode=\"interactive\"\n      keyboardShouldPersistTaps=\"handled\">\n      <View style={[a.w_full, a.gap_md]}>\n        {totalCount > 0 && (\n          <View\n            style={[\n              a.flex_row,\n              a.align_center,\n              a.justify_between,\n              a.gap_md,\n              a.px_lg,\n              a.pt_sm,\n            ]}>\n            <Text style={[a.flex_1, a.text_md, a.font_semi_bold]}>\n              <Trans>Recent searches</Trans>\n            </Text>\n            {totalCount > 1 && (\n              <Button\n                label={l`Clear all recent searches`}\n                onPress={() => clearAllPromptControl.open()}\n                size=\"tiny\"\n                color=\"secondary\"\n                style={[a.flex_shrink_0]}\n                testID=\"searchHistoryClearAllBtn\">\n                <ButtonText>\n                  <Trans context=\"action\">Clear all</Trans>\n                </ButtonText>\n              </Button>\n            )}\n          </View>\n        )}\n\n        {selectedProfiles.length > 0 && (\n          <View>\n            <BlockDrawerGesture>\n              <ScrollView\n                horizontal\n                keyboardShouldPersistTaps=\"handled\"\n                showsHorizontalScrollIndicator={false}\n                contentContainerStyle={[\n                  a.px_lg,\n                  a.flex_row,\n                  a.flex_nowrap,\n                  a.gap_xl,\n                ]}>\n                {moderationOpts &&\n                  selectedProfiles.map((profile, index) => (\n                    <RecentProfileItem\n                      key={profile.did}\n                      profile={profile}\n                      moderationOpts={moderationOpts}\n                      onPress={() => {\n                        ax.metric('search:recent:press', {\n                          profileDid: profile.did,\n                          position: index,\n                        })\n                        onProfileClick(profile)\n                      }}\n                      onRemove={() => onRemoveProfileClick(profile)}\n                    />\n                  ))}\n              </ScrollView>\n            </BlockDrawerGesture>\n          </View>\n        )}\n\n        {searchHistory.length > 0 && (\n          <View style={[a.pt_sm]}>\n            {searchHistory.slice(0, 5).map((historyItem, index) => {\n              const {q, filters} = parseHistoryEntry(historyItem)\n              const filterCount = countActiveFilters(filters)\n\n              return (\n                <SearchHistoryItem\n                  key={index}\n                  q={q}\n                  filterCount={filterCount}\n                  onPress={() => {\n                    ax.metric('search:query', {\n                      source: 'history',\n                      filterCount,\n                    })\n                    onItemClick(historyItem)\n                  }}\n                  onRemove={() => onRemoveItemClick(historyItem)}\n                />\n              )\n            })}\n          </View>\n        )}\n      </View>\n\n      <Prompt.Basic\n        control={clearAllPromptControl}\n        title={l`Clear all recent searches?`}\n        description={l`This can\u2019t be undone, and all of your recent searches will be removed.`}\n        onConfirm={onClearAll}\n        confirmButtonCta={l({message: 'Clear', context: 'action'})}\n        cancelButtonCta={l`Cancel`}\n        confirmButtonColor=\"negative\"\n      />\n    </Layout.Content>\n  )\n}","file":"src/screens/Search/components/SearchHistory.tsx","kind":"component","line":27,"members":{"ax":[44,44],"clearAllPromptControl":[47,47],"moderationOpts":[46,46],"onClearAll":[27,43],"onItemClick":[27,43],"onProfileClick":[27,43],"onRemoveItemClick":[27,43],"onRemoveProfileClick":[27,43],"searchHistory":[27,43],"selectedProfiles":[27,43]},"supers":[]},"SearchResults":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-widgets","Screen \u00b7 component composition"],["search","h-sequence","Search for a topic \u00b7 sequence"]],"code":"let SearchResults = ({\n  query,\n  filters,\n  hasFilters,\n  fromMe,\n  activeTab,\n  onPageSelected,\n  headerHeight,\n}: {\n  query: string\n  filters: SearchFilters\n  hasFilters: boolean\n  fromMe: boolean\n  activeTab: number\n  onPageSelected: (page: number) => void\n  headerHeight: number\n}): React.ReactNode => {\n  const {t: l} = useLingui()\n  /*\n   * People/Feeds visibility keys off post-only filters: a `lang` filter applies\n   * to people and feeds too, so it must not hide those tabs (which would also\n   * regress the non-v2 legacy language dropdown). Other filters are post-only.\n   */\n  const hasPostFilters = hasPostOnlyFilters(filters) || fromMe\n  const activePage = hasPostFilters && activeTab > 1 ? 0 : activeTab\n  const tabShape = hasPostFilters ? 'filtered' : 'plain'\n\n  const sections = useMemo(() => {\n    if (!query && !hasFilters) return []\n    /*\n     * People and Feeds tabs only make sense without post-restricting filters -\n     * those filters don't apply to actors or feeds.\n     */\n    const noFilters = !hasPostFilters\n    return [\n      {\n        title: l`Top`,\n        component: (\n          <SearchScreenPostResults\n            hasFilters={hasFilters}\n            query={query}\n            filters={filters}\n            sort=\"top\"\n            active={activePage === 0}\n          />\n        ),\n      },\n      {\n        title: l`Latest`,\n        component: (\n          <SearchScreenPostResults\n            hasFilters={hasFilters}\n            query={query}\n            filters={filters}\n            sort=\"latest\"\n            active={activePage === 1}\n          />\n        ),\n      },\n      noFilters && {\n        title: l`People`,\n        component: (\n          <SearchScreenUserResults query={query} active={activePage === 2} />\n        ),\n      },\n      noFilters && {\n        title: l`Feeds`,\n        component: (\n          <SearchScreenFeedsResults query={query} active={activePage === 3} />\n        ),\n      },\n      noFilters && {\n        title: l`Starter Packs`,\n        component: (\n          <SearchScreenStarterPackResults\n            query={query}\n            active={activePage === 4}\n          />\n        ),\n      },\n    ].filter(Boolean) as {\n      title: string\n      component: React.ReactNode\n    }[]\n  }, [l, query, filters, hasFilters, hasPostFilters, activePage])\n\n  // There may be fewer tabs after changing the search options.\n  const selectedPage = activePage > sections.length - 1 ? 0 : activePage\n\n  return (\n    <Pager\n      key={tabShape}\n      onPageSelected={onPageSelected}\n      renderTabBar={props => (\n        <Layout.Center style={[a.z_10, web([a.sticky, {top: headerHeight}])]}>\n          <TabBar items={sections.map(section => section.title)} {...props} />\n        </Layout.Center>\n      )}\n      initialPage={selectedPage}>\n      {sections.map((section, i) => (\n        <View key={i}>{section.component}</View>\n      ))}\n    </Pager>\n  )\n}","file":"src/screens/Search/SearchResults.tsx","kind":"component","line":42,"members":{"activeTab":[42,58],"filters":[42,58],"fromMe":[42,58],"hasFilters":[42,58],"headerHeight":[42,58],"onPageSelected":[42,58],"query":[42,58],"sections":[69,126]},"supers":[]},"SearchScreen":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"]],"code":"export function SearchScreen(\n  props: NativeStackScreenProps<SearchTabNavigatorParams, 'Search'>,\n) {\n  const queryParam = props.route?.params?.q ?? ''\n\n  return (\n    <SearchScreenShell\n      queryParam={queryParam}\n      testID=\"searchScreen\"\n      isExplore\n    />\n  )\n}","file":"src/screens/Search/index.tsx","kind":"component","line":7,"members":{},"supers":[]},"SearchScreenFeedsResults":{"appearsIn":[["search","h-widgets","Screen \u00b7 component composition"]],"code":"let SearchScreenFeedsResults = ({\n  query,\n  active,\n}: {\n  query: string\n  active: boolean\n}): React.ReactNode => {\n  const ax = useAnalytics()\n  const t = useTheme()\n\n  const {\n    data: results,\n    isFetched,\n    isFetching,\n    error,\n    fetchNextPage,\n    isFetchingNextPage,\n    hasNextPage,\n  } = usePopularFeedsSearch({\n    query,\n    enabled: active,\n  })\n  const feeds = useMemo(() => {\n    return results?.pages.flatMap(page => page.feeds) || []\n  }, [results])\n  const onEndReached = useCallback(() => {\n    if (isFetching || !hasNextPage || error) return\n    void fetchNextPage()\n  }, [isFetching, error, hasNextPage, fetchNextPage])\n\n  const fireTracking = useCallOnce(() => {\n    ax.metric('search:results:loaded', {\n      tab: 'feeds',\n      initialCount: feeds.length,\n    })\n  })\n  if (isFetched) {\n    fireTracking()\n  }\n\n  return isFetched ? (\n    <>\n      {feeds.length || hasNextPage ? (\n        <List\n          data={feeds}\n          renderItem={({\n            item,\n            index,\n          }: {\n            item: app.bsky.feed.defs.GeneratorView\n            index: number\n          }) => (\n            <View\n              style={[\n                a.border_t,\n                t.atoms.border_contrast_low,\n                a.px_lg,\n                a.py_lg,\n              ]}>\n              <SearchFeedCard position={index} view={item} />\n            </View>\n          )}\n          keyExtractor={(item: app.bsky.feed.defs.GeneratorView) => item.uri}\n          onEndReached={onEndReached}\n          desktopFixedHeight\n          ListFooterComponent={\n            <ListFooter\n              hasNextPage={hasNextPage}\n              isFetchingNextPage={isFetchingNextPage}\n            />\n          }\n        />\n      ) : (\n        <EmptyState messageText={<NoResultsText query={query} />} />\n      )}\n    </>\n  ) : (\n    <Loader />\n  )\n}","file":"src/screens/Search/SearchResults.tsx","kind":"component","line":627,"members":{"active":[627,633],"ax":[634,634],"feeds":[649,651],"fireTracking":[657,662],"onEndReached":[652,655],"query":[627,633],"t":[635,635]},"supers":[]},"SearchScreenInner":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"]],"code":"let SearchScreenInner = ({\n  activeTab,\n  setActiveTab,\n  query,\n  filters,\n  hasFilters,\n  fromMe,\n  headerHeight,\n  focusSearchInput,\n}: {\n  activeTab: number\n  setActiveTab: React.Dispatch<React.SetStateAction<number>>\n  query: string\n  filters: SearchFilters\n  hasFilters: boolean\n  fromMe: boolean\n  headerHeight: number\n  focusSearchInput: (tab?: TabParam) => void\n}): React.ReactNode => {\n  const t = useTheme()\n  const {hasSession} = useSession()\n  const {gtTablet} = useBreakpoints()\n\n  const onPageSelected = (index: number) => {\n    setActiveTab(index)\n  }\n\n  return query || hasFilters ? (\n    <SearchResults\n      query={query}\n      filters={filters}\n      hasFilters={hasFilters}\n      fromMe={fromMe}\n      activeTab={activeTab}\n      headerHeight={headerHeight}\n      onPageSelected={onPageSelected}\n    />\n  ) : hasSession ? (\n    <Explore focusSearchInput={focusSearchInput} headerHeight={headerHeight} />\n  ) : (\n    <Layout.Center>\n      <View style={a.flex_1}>\n        {gtTablet && (\n          <View\n            style={[\n              a.border_b,\n              t.atoms.border_contrast_low,\n              a.px_lg,\n              a.pt_sm,\n              a.pb_lg,\n            ]}>\n            <Text style={[a.text_2xl, a.font_bold]}>\n              <Trans>Search</Trans>\n            </Text>\n          </View>\n        )}\n\n        <View style={[a.align_center, a.justify_center, a.py_4xl, a.gap_lg]}>\n          <MagnifyingGlassIcon\n            strokeWidth={3}\n            size={60}\n            style={t.atoms.text_contrast_medium as StyleProp<ViewStyle>}\n          />\n          <Text style={[t.atoms.text_contrast_medium, a.text_md]}>\n            <Trans>Find posts, users, and feeds on Bluesky</Trans>\n          </Text>\n        </View>\n      </View>\n    </Layout.Center>\n  )\n}","file":"src/screens/Search/Shell.tsx","kind":"component","line":726,"members":{"activeTab":[726,744],"filters":[726,744],"focusSearchInput":[726,744],"fromMe":[726,744],"hasFilters":[726,744],"headerHeight":[726,744],"onPageSelected":[749,751],"query":[726,744],"setActiveTab":[726,744],"t":[745,745]},"supers":[]},"SearchScreenPostResults":{"appearsIn":[["search","h-widgets","Screen \u00b7 component composition"]],"code":"let SearchScreenPostResults = ({\n  hasFilters = false,\n  query,\n  filters,\n  sort,\n  active,\n}: {\n  hasFilters: boolean\n  query: string\n  filters?: SearchFilters\n  sort?: 'top' | 'latest'\n  active: boolean\n}): React.ReactNode => {\n  const ax = useAnalytics()\n  const {t: l} = useLingui()\n  const {hasSession} = useSession()\n  const [isPTR, setIsPTR] = useState(false)\n  const trackPostView = usePostViewTracking('SearchResults')\n\n  const augmentedV2Query = useMemo(() => {\n    return augmentSearchQuery(query || '')\n  }, [query])\n\n  const v2 = useSearchPostsV2Query({\n    query: augmentedV2Query,\n    filters,\n    sort,\n    enabled: active,\n  })\n  const {\n    isFetched,\n    data: results,\n    isFetching,\n    error,\n    refetch,\n    fetchNextPage,\n    isFetchingNextPage,\n    hasNextPage,\n  } = v2\n\n  const t = useTheme()\n  const onPullToRefresh = useCallback(async () => {\n    setIsPTR(true)\n    await refetch()\n    setIsPTR(false)\n  }, [setIsPTR, refetch])\n  const onEndReached = useCallback(() => {\n    if (isFetching || !hasNextPage || error) return\n    void fetchNextPage()\n  }, [isFetching, error, hasNextPage, fetchNextPage])\n\n  const posts = useMemo(() => {\n    return results?.pages.flatMap(page => page.posts) || []\n  }, [results])\n  const items = useMemo(() => {\n    let temp: SearchResultSlice[] = []\n\n    const seenUris = new Set()\n    for (const post of posts) {\n      if (seenUris.has(post.uri)) {\n        continue\n      }\n      temp.push({\n        type: 'post',\n        key: post.uri,\n        post,\n      })\n      seenUris.add(post.uri)\n    }\n\n    if (isFetchingNextPage) {\n      temp.push({\n        type: 'loadingMore',\n        key: 'loadingMore',\n      })\n    }\n\n    return temp\n  }, [posts, isFetchingNextPage])\n\n  const closeAllActiveElements = useCloseAllActiveElements()\n  const {requestSwitchToAccount} = useLoggedOutViewControls()\n\n  const fireTracking = useCallOnce(() => {\n    if (sort) {\n      // ts only\n      ax.metric('search:results:loaded', {\n        tab: sort,\n        initialCount: items.length,\n      })\n    }\n  })\n  if (isFetched && sort) {\n    fireTracking()\n  }\n\n  const showSignIn = () => {\n    closeAllActiveElements()\n    requestSwitchToAccount({requestedAccount: 'none'})\n  }\n\n  const showCreateAccount = () => {\n    closeAllActiveElements()\n    requestSwitchToAccount({requestedAccount: 'new'})\n  }\n\n  if (!hasSession) {\n    return (\n      <SearchError title={l`Search is currently unavailable when logged out`}>\n        <Text style={[a.text_md, a.text_center, a.leading_snug]}>\n          <Trans>\n            <InlineLinkText label={l`Sign in`} to=\"#\" onPress={showSignIn}>\n              Sign in\n            </InlineLinkText>\n            <Text style={t.atoms.text_contrast_medium}> or </Text>\n            <InlineLinkText\n              label={l`Create an account`}\n              to={'#'}\n              onPress={showCreateAccount}>\n              create an account\n            </InlineLinkText>\n            <Text> </Text>\n            <Text style={t.atoms.text_contrast_medium}>\n              to search for news, sports, politics, and everything else\n              happening on Bluesky.\n            </Text>\n          </Trans>\n        </Text>\n      </SearchError>\n    )\n  }\n\n  return error ? (\n    <EmptyState\n      messageText={\n        shouldRetryError(error) || isNetworkError(error)\n          ? l`We\u2019re sorry, but your search could not be completed. Please try again in a few minutes.`\n          : l`We\u2019re sorry, but your search could not be completed.`\n      }\n      error={cleanError(error)}\n    />\n  ) : (\n    <>\n      {isFetched ? (\n        <>\n          {posts.length ? (\n            <List\n              data={items}\n              renderItem={({\n                item,\n                index,\n              }: {\n                item: SearchResultSlice\n                index: number\n              }) => {\n                if (item.type === 'post') {\n                  return (\n                    <SearchPost from={sort} position={index} post={item.post} />\n                  )\n                } else {\n                  return null\n                }\n              }}\n              keyExtractor={(item: SearchResultSlice) => item.key}\n              refreshing={isPTR}\n              onRefresh={() => {\n                void onPullToRefresh()\n              }}\n              onEndReached={onEndReached}\n              onItemSeen={(item: SearchResultSlice) => {\n                if (item.type === 'post') {\n                  trackPostView(item.post)\n                }\n              }}\n              desktopFixedHeight\n              ListFooterComponent={\n                <ListFooter\n                  isFetchingNextPage={isFetchingNextPage}\n                  hasNextPage={hasNextPage}\n                />\n              }\n            />\n          ) : (\n            <EmptyState\n              messageText={\n                <NoResultsText hasFilters={hasFilters} query={query} />\n              }\n            />\n          )}\n        </>\n      ) : (\n        <Loader />\n      )}\n    </>\n  )\n}","file":"src/screens/Search/SearchResults.tsx","kind":"component","line":288,"members":{"active":[288,300],"augmentedV2Query":[307,309],"ax":[301,301],"closeAllActiveElements":[368,368],"filters":[288,300],"fireTracking":[371,379],"hasFilters":[288,300],"isPTR":[304,304],"items":[342,366],"onEndReached":[334,337],"onPullToRefresh":[329,333],"posts":[339,341],"query":[288,300],"showCreateAccount":[389,392],"showSignIn":[384,387],"sort":[288,300],"t":[328,328],"trackPostView":[305,305],"v2":[311,316]},"supers":[]},"SearchScreenShell":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["search","h-classes","Logic \u00b7 class diagram"],["search","h-widgets","Screen \u00b7 component composition"],["search","h-sequence","Search for a topic \u00b7 sequence"]],"code":"export function SearchScreenShell({\n  queryParam,\n  testID,\n  fixedParams,\n  navButton = 'menu',\n  inputPlaceholder,\n  isExplore,\n}: {\n  queryParam: string\n  testID: string\n  fixedParams?: SearchFilters\n  navButton?: 'back' | 'menu'\n  inputPlaceholder?: string\n  isExplore?: boolean\n}) {\n  const ax = useAnalytics()\n  const t = useTheme()\n  const {gtMobile} = useBreakpoints()\n  const navigation =\n    useNavigation<\n      NavigationProp<CommonNavigatorParams, 'Search' | 'ProfileSearch'>\n    >()\n  const route = useRoute()\n  const textInput = useRef<React.ComponentRef<typeof TextInput>>(null)\n  const {t: l} = useLingui()\n  const {currentAccount} = useSession()\n  const queryClient = useQueryClient()\n  const isFocused = useIsFocused()\n\n  useViewportZoomLock({enabled: isFocused})\n\n  // Get tab parameter from route params\n  const tabParam = (route.params as {q?: string; tab?: TabParam})?.tab\n  const [activeTab, setActiveTab] = useState(() => getTabIndex(tabParam))\n\n  /*\n   * A raw `from:me` operator stays visible in the search input. Submitting the\n   * advanced dialog promotes it to a structured `from=me` filter and removes\n   * it from `q`; the API layer reconstructs the operator for post search.\n   */\n  const {query, fromMe, filters, setFilters, hasFilters} = useQueryManager({\n    initialQuery: queryParam,\n    fixedParams,\n  })\n\n  // Query terms\n  const [searchText, setSearchText] = useState<string>(query)\n  const searchTextRef = useRef(searchText)\n  const updateSearchText = useCallback((text: string) => {\n    searchTextRef.current = text\n    setSearchText(text)\n  }, [])\n\n  const {items: autocompleteItems, isFetching: isAutocompleteFetching} =\n    useAutocomplete({\n      type: 'profile',\n      /*\n       * On web the dropdown (SearchAutocompleteInput) owns its own autocomplete\n       * query; only the native inline list consumes this one, so pass an empty\n       * query on web to keep the hook a no-op instead of doing wasted work.\n       */\n      query: IS_NATIVE ? searchText : '',\n    })\n\n  const [showAutocomplete, setShowAutocomplete] = useState(false)\n\n  const [termHistory = [], setTermHistory] = useStorage(account, [\n    currentAccount?.did ?? 'pwi',\n    'searchTermHistory',\n  ] as const)\n  const [accountHistory = [], setAccountHistory] = useStorage(account, [\n    currentAccount?.did ?? 'pwi',\n    'searchAccountHistory',\n  ])\n\n  const {data: accountHistoryProfiles} = useProfilesQuery({\n    handles: accountHistory,\n    maintainData: true,\n  })\n\n  const updateSearchHistory = useCallback(\n    (q: string, searchFilters: SearchFilters = {}) => {\n      if (!q) return\n      /*\n       * Store the query plus any advanced-search filters. Term-only searches\n       * serialize to a plain string (back-compatible with existing history);\n       * filtered searches serialize to JSON. Dedupe on the serialized form.\n       */\n      const item = serializeHistoryEntry(q, searchFilters)\n      const newSearchHistory = [\n        item,\n        ...termHistory.filter(search => search !== item),\n      ].slice(0, 6)\n      setTermHistory(newSearchHistory)\n    },\n    [termHistory, setTermHistory],\n  )\n\n  const updateProfileHistory = useCallback(\n    (item: bsky.profile.AnyProfileView) => {\n      const newAccountHistory = [\n        item.did,\n        ...accountHistory.filter(p => p !== item.did),\n      ].slice(0, 10)\n      setAccountHistory(newAccountHistory)\n    },\n    [accountHistory, setAccountHistory],\n  )\n\n  const deleteSearchHistoryItem = useCallback(\n    (item: string) => {\n      setTermHistory(termHistory.filter(search => search !== item))\n    },\n    [termHistory, setTermHistory],\n  )\n  const deleteProfileHistoryItem = useCallback(\n    (item: bsky.profile.AnyProfileView) => {\n      setAccountHistory(accountHistory.filter(p => p !== item.did))\n    },\n    [accountHistory, setAccountHistory],\n  )\n  const clearAllHistory = useCallback(() => {\n    ax.metric('search:recent:clearAll', {\n      termCount: termHistory.length,\n      profileCount: accountHistory.length,\n    })\n    setTermHistory([])\n    setAccountHistory([])\n  }, [ax, termHistory, accountHistory, setTermHistory, setAccountHistory])\n\n  const showFilters = Boolean((query || hasFilters) && !showAutocomplete)\n\n  const onChangeLang = useCallback(\n    (lang: string) => {\n      setFilters({...filters, lang: lang || undefined})\n    },\n    [filters, setFilters],\n  )\n\n  // web only - measure header height for sticky positioning\n  const [headerHeight, setHeaderHeight] = useState(0)\n  const headerRef = useRef(null)\n  useLayoutEffect(() => {\n    if (IS_WEB) {\n      if (!headerRef.current) return\n      const measurement = (headerRef.current as Element).getBoundingClientRect()\n      setHeaderHeight(measurement.height)\n    }\n  }, [])\n\n  /*\n   * On native, navigating to an already-mounted Search screen with a new `q`\n   * (e.g. from a post hashtag/search link) updates the route param without\n   * remounting, so re-sync the input. Web handles this via the focus effect\n   * below, which fires on back/forward navigation.\n   */\n  useEffect(() => {\n    if (IS_NATIVE) {\n      // eslint-disable-next-line react-hooks/set-state-in-effect\n      updateSearchText(query)\n    }\n  }, [query, updateSearchText])\n  useFocusEffect(\n    useNonReactiveCallback(() => {\n      if (IS_WEB) {\n        updateSearchText(query)\n      }\n    }),\n  )\n\n  const onPressClearQuery = useCallback(() => {\n    scrollToTopWeb()\n    /*\n     * Clearing the query also resets any advanced-search filters, then keeps\n     * the input focused so the user can immediately type a new search.\n     */\n    if (IS_WEB) {\n      /*\n       * Replace the param set so q/tab/filters drop out of the URL instead of\n       * serializing as the literal string \"undefined\". fixedParams live on the\n       * route already and are preserved by withoutSearchParams.\n       */\n      const parameters = withoutSearchParams(\n        route.params as Record<string, unknown>,\n      )\n      // @ts-expect-error route is not typesafe\n      navigation.replace(route.name, parameters)\n    } else {\n      updateSearchText('')\n      navigation.setParams({...filtersToRouteParams({}), q: ''})\n    }\n    textInput.current?.focus()\n  }, [updateSearchText, navigation, route])\n\n  const onChangeText = useCallback(\n    (text: string) => {\n      scrollToTopWeb()\n      updateSearchText(text)\n    },\n    [updateSearchText],\n  )\n\n  const navigateToItem = useCallback(\n    (item: string, itemFilters: SearchFilters = filters) => {\n      scrollToTopWeb()\n      setShowAutocomplete(false)\n      updateSearchHistory(item, itemFilters)\n\n      if (IS_WEB) {\n        const nextParams = {\n          ...withoutFilterParams(route.params as Record<string, unknown>),\n          ...definedFilterParams(itemFilters),\n          q: item,\n        }\n        // @ts-expect-error route is not typesafe\n        navigation.push(route.name, nextParams)\n      } else {\n        textInput.current?.blur()\n        navigation.setParams({...filtersToRouteParams(itemFilters), q: item})\n      }\n    },\n    [updateSearchHistory, navigation, route, filters],\n  )\n\n  const onPressCancelSearch = useCallback(() => {\n    scrollToTopWeb()\n    textInput.current?.blur()\n    setShowAutocomplete(false)\n    if (IS_WEB) {\n      /*\n       * Empty params resets the URL to be /search rather than /search?q=\n       * Also clear tab and advanced-search filter parameters.\n       */\n      const parameters = withoutSearchParams(\n        route.params as Record<string, unknown>,\n      )\n      // @ts-expect-error route is not typesafe\n      navigation.replace(route.name, parameters)\n    } else {\n      updateSearchText('')\n      navigation.setParams({\n        ...filtersToRouteParams({}),\n        q: '',\n        tab: undefined,\n      })\n    }\n  }, [\n    setShowAutocomplete,\n    updateSearchText,\n    navigation,\n    route.params,\n    route.name,\n  ])\n\n  const onSubmit = (source: 'typed' | 'autocomplete') => () => {\n    const nextQuery = searchTextRef.current\n    ax.metric('search:query', {\n      source,\n      filterCount: countActiveFilters(filters),\n    })\n    navigateToItem(nextQuery)\n  }\n\n  const onSubmitAdvanced = useCallback(\n    (text: string, nextFilters: SearchFilters) => {\n      scrollToTopWeb()\n      setShowAutocomplete(false)\n      updateSearchText(text)\n      updateSearchHistory(text, nextFilters)\n      ax.metric('search:query', {\n        source: 'typed',\n        filterCount: countActiveFilters(nextFilters),\n      })\n      if (IS_WEB) {\n        /*\n         * Build a fresh param set so removed filters drop out of the URL.\n         * Only defined filters are included - undefined values would serialize\n         * as the literal string \"undefined\".\n         */\n        const nextParams = {\n          ...withoutFilterParams(route.params as Record<string, unknown>),\n          ...definedFilterParams(nextFilters),\n          q: text,\n        }\n        // @ts-expect-error route is not typesafe\n        navigation.push(route.name, nextParams)\n      } else {\n        textInput.current?.blur()\n        // setParams merges, so pass undefined for absent keys to clear them.\n        navigation.setParams({...filtersToRouteParams(nextFilters), q: text})\n      }\n    },\n    [ax, navigation, route, updateSearchText, updateSearchHistory],\n  )\n\n  const onAutocompleteResultPress = useCallback(() => {\n    if (IS_WEB) {\n      setShowAutocomplete(false)\n    } else {\n      textInput.current?.blur()\n    }\n  }, [])\n\n  const handleHistoryItemClick = useCallback(\n    (item: string) => {\n      /*\n       * History entries may carry advanced-search filters (JSON-encoded);\n       * term-only entries are plain strings. Restore both the query and\n       * filters.\n       */\n      const {q, filters: itemFilters} = parseHistoryEntry(item)\n      updateSearchText(q)\n      navigateToItem(q, itemFilters)\n    },\n    [navigateToItem, updateSearchText],\n  )\n\n  const handleProfileClick = useCallback(\n    (profile: bsky.profile.AnyProfileView) => {\n      updateSearchText('')\n      unstableCacheProfileView(queryClient, profile)\n      // Slight delay to avoid updating during push nav animation.\n      setTimeout(() => {\n        updateProfileHistory(profile)\n      }, 400)\n    },\n    [updateProfileHistory, queryClient, updateSearchText],\n  )\n\n  /**\n   * Web only. Selecting a profile from the anchored autocomplete dropdown.\n   */\n  const onSelectProfile = useCallback(\n    (profile: bsky.profile.AnyProfileView, position: number) => {\n      ax.metric('search:autocomplete:press', {\n        profileDid: profile.did,\n        position,\n      })\n      handleProfileClick(profile)\n      navigation.navigate('Profile', {name: profile.handle})\n    },\n    [ax, handleProfileClick, navigation],\n  )\n\n  /**\n   * Web only. Selecting the \"Search for X\" row from the anchored autocomplete\n   * dropdown. This runs the typed query as-is (not a suggested profile), so it\n   * is attributed to `typed` rather than `autocomplete`.\n   */\n  const onSelectSearch = useCallback(\n    (value: string) => {\n      ax.metric('search:query', {\n        source: 'typed',\n        filterCount: countActiveFilters(filters),\n      })\n      updateSearchText(value)\n      navigateToItem(value)\n    },\n    [ax, filters, navigateToItem, updateSearchText],\n  )\n\n  const onSoftReset = useCallback(() => {\n    if (IS_WEB) {\n      /*\n       * Empty params resets the URL to be /search rather than /search?q=\n       * Also clear tab and advanced-search filter parameters.\n       */\n      const parameters = withoutSearchParams(\n        route.params as Record<string, unknown>,\n      )\n      // @ts-expect-error route is not typesafe\n      navigation.replace(route.name, parameters)\n    } else {\n      updateSearchText('')\n      navigation.setParams({\n        ...filtersToRouteParams({}),\n        q: '',\n        tab: undefined,\n      })\n      textInput.current?.focus()\n    }\n  }, [navigation, route.name, route.params, updateSearchText])\n\n  useFocusEffect(\n    useCallback(() => {\n      return listenSoftReset(onSoftReset)\n    }, [onSoftReset]),\n  )\n\n  const onSearchInputFocus = useCallback(() => {\n    if (IS_WEB) {\n      // Prevent a jump on iPad by ensuring that\n      // the initial focused render has no result list.\n      requestAnimationFrame(() => {\n        setShowAutocomplete(true)\n      })\n    } else {\n      setShowAutocomplete(true)\n    }\n  }, [setShowAutocomplete])\n\n  const focusSearchInput = useCallback(\n    (tab?: TabParam) => {\n      textInput.current?.focus()\n\n      // If a tab is specified, set the tab parameter\n      if (tab) {\n        if (IS_WEB) {\n          navigation.setParams({...route.params, tab})\n        } else {\n          navigation.setParams({tab})\n        }\n      }\n    },\n    [navigation, route],\n  )\n\n  const onShareSearch = useCallback(() => {\n    const url = new URL('https://bsky.app')\n    url.pathname = '/search'\n    if (query) url.searchParams.set('q', query)\n    for (const [key, value] of Object.entries(definedFilterParams(filters))) {\n      url.searchParams.set(key, value)\n    }\n    ax.metric('search:shareLink:press', {\n      filterCount: countActiveFilters(filters),\n    })\n    setStringAsync(url.toString()).then(\n      () => Toast.show(l`Copied link to clipboard`, {type: 'success'}),\n      () => Toast.show(l`Failed to copy link`, {type: 'error'}),\n    )\n  }, [ax, query, filters, l])\n\n  const showHeader = !gtMobile || navButton !== 'menu'\n\n  return (\n    <Layout.Screen testID={testID}>\n      <View\n        ref={headerRef}\n        onLayout={evt => {\n          if (IS_WEB) setHeaderHeight(evt.nativeEvent.layout.height)\n        }}\n        style={[\n          a.relative,\n          a.z_10,\n          web({\n            position: 'sticky',\n            top: 0,\n          }),\n        ]}>\n        <Layout.Center style={t.atoms.bg}>\n          {showHeader && (\n            <View\n              // HACK: shift up search input. we can't remove the top padding\n              // on the search input because it messes up the layout animation\n              // if we add it only when the header is hidden\n              style={{marginBottom: tokens.space.xs * -1}}>\n              <Layout.Header.Outer noBottomBorder>\n                {navButton === 'menu' ? (\n                  <Layout.Header.MenuButton />\n                ) : (\n                  <Layout.Header.BackButton />\n                )}\n                <Layout.Header.Content align=\"left\">\n                  <Layout.Header.TitleText>\n                    {isExplore ? <Trans>Explore</Trans> : <Trans>Search</Trans>}\n                  </Layout.Header.TitleText>\n                </Layout.Header.Content>\n                {showFilters ? (\n                  <View style={[a.flex_row, a.align_center, a.gap_sm]}>\n                    <AdvancedSearchDialog\n                      disabled={activeTab > 1}\n                      q={searchText}\n                      filters={filters}\n                      onSubmit={onSubmitAdvanced}\n                    />\n                    <Button\n                      accessibilityRole=\"button\"\n                      size=\"small\"\n                      color=\"secondary\"\n                      shape=\"round\"\n                      label={l`Share this search`}\n                      onPress={onShareSearch}>\n                      <ButtonIcon icon={ShareIcon} />\n                    </Button>\n                  </View>\n                ) : (\n                  <Layout.Header.Slot />\n                )}\n              </Layout.Header.Outer>\n            </View>\n          )}\n          <View style={[a.px_lg, a.pt_sm, a.pb_sm, a.overflow_hidden]}>\n            <View style={[a.gap_sm]}>\n              {!!query && !showAutocomplete && (\n                <DetectedLanguagesAdmonition\n                  query={query}\n                  filters={filters}\n                  sort={activeTab === 1 ? 'latest' : 'top'}\n                  enabled={activeTab === 0 || activeTab === 1}\n                  onPressLanguage={onChangeLang}\n                />\n              )}\n\n              <View style={[a.w_full, a.flex_row, a.align_stretch, a.gap_sm]}>\n                <View style={[a.flex_1, a.flex_row, a.align_center, a.gap_sm]}>\n                  {showAutocomplete && (\n                    <Button\n                      label={l`Cancel search`}\n                      size=\"small\"\n                      variant=\"ghost\"\n                      color=\"secondary\"\n                      shape=\"round\"\n                      style={[a.px_sm]}\n                      onPress={onPressCancelSearch}\n                      hitSlop={HITSLOP_10}>\n                      <ButtonIcon icon={ArrowLeftIcon} size=\"lg\" />\n                    </Button>\n                  )}\n                  <View style={[a.flex_1]}>\n                    <SearchAutocompleteInput\n                      testID=\"searchScreenInput\"\n                      ref={textInput}\n                      value={searchText}\n                      onFocus={onSearchInputFocus}\n                      onChangeText={onChangeText}\n                      onClearText={onPressClearQuery}\n                      onSubmitEditing={onSubmit('typed')}\n                      placeholder={inputPlaceholder ?? l`Search`}\n                      hitSlop={{...HITSLOP_20, top: 0}}\n                      hotkey={true}\n                      fixedParams={Boolean(fixedParams)}\n                      onSelectProfile={onSelectProfile}\n                      onSelectSearch={onSelectSearch}\n                    />\n                  </View>\n                </View>\n                {showFilters && !showHeader ? (\n                  <View style={[a.flex_row, a.align_center, a.gap_sm]}>\n                    <AdvancedSearchDialog\n                      disabled={activeTab > 1}\n                      q={searchText}\n                      filters={filters}\n                      onSubmit={onSubmitAdvanced}\n                    />\n                    <Button\n                      accessibilityRole=\"button\"\n                      size=\"small\"\n                      color=\"secondary\"\n                      shape=\"round\"\n                      label={l`Share this search`}\n                      onPress={onShareSearch}>\n                      <ButtonIcon icon={ShareIcon} />\n                    </Button>\n                  </View>\n                ) : null}\n              </View>\n            </View>\n          </View>\n        </Layout.Center>\n      </View>\n\n      <View style={[a.flex_1, a.relative]}>\n        <View style={[a.flex_1, web(showAutocomplete && a.hidden)]}>\n          <SearchScreenInner\n            key={filters.lang ?? ''}\n            activeTab={activeTab}\n            setActiveTab={setActiveTab}\n            query={query}\n            filters={filters}\n            hasFilters={hasFilters}\n            fromMe={fromMe}\n            headerHeight={headerHeight}\n            focusSearchInput={focusSearchInput}\n          />\n        </View>\n\n        {showAutocomplete && !fixedParams && (\n          <Animated.View\n            entering={native(FadeInDown.easing(Easing.out(Easing.cubic)))}\n            exiting={native(FadeOutDown.easing(Easing.out(Easing.cubic)))}\n            style={platform({\n              web: [a.flex_1],\n              native: [t.atoms.bg, a.absolute, a.inset_0],\n            })}\n            accessibilityViewIsModal\n            accessibilityRole=\"list\">\n            {searchText.length > 0 && IS_NATIVE ? (\n              <AutocompleteResults\n                items={autocompleteItems}\n                isFetching={isAutocompleteFetching}\n                searchText={searchText}\n                onSubmit={onSubmit('autocomplete')}\n                onResultPress={onAutocompleteResultPress}\n                onProfileClick={handleProfileClick}\n              />\n            ) : (\n              <SearchHistory\n                searchHistory={termHistory}\n                selectedProfiles={\n                  accountHistoryProfiles?.profiles.filter(p =>\n                    accountHistory.includes(p.did),\n                  ) ?? []\n                }\n                onItemClick={handleHistoryItemClick}\n                onProfileClick={handleProfileClick}\n                onRemoveItemClick={deleteSearchHistoryItem}\n                onRemoveProfileClick={deleteProfileHistoryItem}\n                onClearAll={clearAllHistory}\n              />\n            )}\n          </Animated.View>\n        )}\n      </View>\n    </Layout.Screen>\n  )\n}","file":"src/screens/Search/Shell.tsx","kind":"component","line":108,"members":{"accountHistory":[178,181],"activeTab":[141,141],"ax":[123,123],"clearAllHistory":[229,236],"deleteProfileHistoryItem":[223,228],"deleteSearchHistoryItem":[217,222],"fixedParams":[108,122],"focusSearchInput":[509,523],"handleHistoryItemClick":[411,423],"handleProfileClick":[425,435],"headerHeight":[248,248],"headerRef":[249,249],"inputPlaceholder":[108,122],"isExplore":[108,122],"isFocused":[135,135],"navButton":[108,122],"navigateToItem":[310,330],"navigation":[126,129],"onAutocompleteResultPress":[403,409],"onChangeLang":[240,245],"onChangeText":[302,308],"onPressCancelSearch":[332,360],"onPressClearQuery":[278,300],"onSearchInputFocus":[497,507],"onSelectProfile":[440,450],"onSelectSearch":[457,467],"onShareSearch":[525,539],"onSoftReset":[469,489],"onSubmit":[362,369],"onSubmitAdvanced":[371,401],"queryClient":[134,134],"queryParam":[108,122],"route":[130,130],"searchText":[154,154],"searchTextRef":[155,155],"showAutocomplete":[172,172],"t":[124,124],"termHistory":[174,177],"testID":[108,122],"textInput":[131,131],"updateProfileHistory":[206,215],"updateSearchHistory":[188,204],"updateSearchText":[156,159]},"supers":[]},"SearchScreenUserResults":{"appearsIn":[["search","h-widgets","Screen \u00b7 component composition"]],"code":"let SearchScreenUserResults = ({\n  query,\n  active,\n}: {\n  query: string\n  active: boolean\n}): React.ReactNode => {\n  const ax = useAnalytics()\n  const {t: l} = useLingui()\n  const {hasSession} = useSession()\n  const [isPTR, setIsPTR] = useState(false)\n\n  const {\n    isFetched,\n    data: results,\n    isFetching,\n    error,\n    refetch,\n    fetchNextPage,\n    isFetchingNextPage,\n    hasNextPage,\n  } = useActorSearch({\n    query,\n    enabled: active,\n  })\n\n  const onPullToRefresh = useCallback(async () => {\n    setIsPTR(true)\n    await refetch()\n    setIsPTR(false)\n  }, [setIsPTR, refetch])\n  const onEndReached = useCallback(() => {\n    if (!hasSession) return\n    if (isFetching || !hasNextPage || error) return\n    void fetchNextPage()\n  }, [isFetching, error, hasNextPage, fetchNextPage, hasSession])\n\n  const profiles = useMemo(() => {\n    return results?.pages.flatMap(page => page.actors) || []\n  }, [results])\n\n  const fireTracking = useCallOnce(() => {\n    ax.metric('search:results:loaded', {\n      tab: 'people',\n      initialCount: profiles.length,\n    })\n  })\n  if (isFetched) {\n    fireTracking()\n  }\n\n  if (error) {\n    return (\n      <EmptyState\n        messageText={\n          shouldRetryError(error) || isNetworkError(error)\n            ? l`We\u2019re sorry, but your search could not be completed. Please try again in a few minutes.`\n            : l`We\u2019re sorry, but your search could not be completed.`\n        }\n        error={error.toString()}\n      />\n    )\n  }\n\n  return isFetched && profiles ? (\n    <>\n      {profiles.length ? (\n        <List\n          data={profiles}\n          renderItem={({\n            item,\n            index,\n          }: {\n            item: bsky.profile.AnyProfileView\n            index: number\n          }) => <SearchScreenProfileButton position={index} profile={item} />}\n          keyExtractor={(item: bsky.profile.AnyProfileView) => item.did}\n          refreshing={isPTR}\n          onRefresh={() => void onPullToRefresh()}\n          onEndReached={onEndReached}\n          desktopFixedHeight\n          ListFooterComponent={\n            <ListFooter\n              hasNextPage={hasNextPage && hasSession}\n              isFetchingNextPage={isFetchingNextPage}\n            />\n          }\n        />\n      ) : (\n        <EmptyState messageText={<NoResultsText query={query} />} />\n      )}\n    </>\n  ) : (\n    <Loader />\n  )\n}","file":"src/screens/Search/SearchResults.tsx","kind":"component","line":509,"members":{"active":[509,515],"ax":[516,516],"fireTracking":[550,555],"isPTR":[519,519],"onEndReached":[540,544],"onPullToRefresh":[535,539],"profiles":[546,548],"query":[509,515]},"supers":[]},"useActorSearch":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Search for a topic \u00b7 sequence"]],"code":"export function useActorSearch({\n  query,\n  enabled,\n  maintainData,\n  limit = 25,\n}: {\n  query: string\n  enabled?: boolean\n  maintainData?: boolean\n  limit?: number\n}) {\n  const client = useAppviewClient()\n  return useInfiniteQuery<\n    app.bsky.actor.searchActors.$OutputBody,\n    Error,\n    InfiniteData<app.bsky.actor.searchActors.$OutputBody>,\n    QueryKey,\n    string | undefined\n  >({\n    staleTime: STALE.MINUTES.FIVE,\n    queryKey: RQKEY(query, limit),\n    queryFn: async ({pageParam}) => {\n      return await client.call(app.bsky.actor.searchActors, {\n        q: query,\n        limit,\n        cursor: pageParam,\n      })\n    },\n    enabled: enabled && !!query,\n    initialPageParam: undefined,\n    getNextPageParam: lastPage => lastPage.cursor,\n    placeholderData: maintainData ? keepPreviousData : undefined,\n    select,\n  })\n}","file":"src/state/queries/actor-search.ts","kind":"hook","line":20,"members":{"client":[31,31]},"supers":[]},"usePopularFeedsSearch":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"]],"code":"export function usePopularFeedsSearch({\n  query,\n  enabled,\n}: {\n  query: string\n  enabled?: boolean\n}) {\n  const client = useAppviewClient()\n  const moderationOpts = useModerationOpts()\n  const enabledInner = enabled ?? Boolean(moderationOpts)\n\n  return useInfiniteQuery({\n    enabled: enabledInner,\n    queryKey: createPopularFeedsSearchQueryKey(query),\n    queryFn: async ({pageParam}) => {\n      const data = await client.call(\n        app.bsky.unspecced.getPopularFeedGenerators,\n        {\n          limit: 15,\n          query: query,\n          cursor: pageParam,\n        },\n      )\n\n      return data\n    },\n    initialPageParam: undefined as string | undefined,\n    getNextPageParam: lastPage => lastPage.cursor,\n    placeholderData: keepPreviousData,\n    select(data) {\n      return {\n        ...data,\n        pages: data.pages.map(page => ({\n          ...page,\n          feeds: page.feeds.filter(feed => {\n            const decision = moderateFeedGenerator(feed, moderationOpts!)\n            return !decision.ui('contentMedia').blur\n          }),\n        })),\n      }\n    },\n  })\n}","file":"src/state/queries/feed.ts","kind":"hook","line":372,"members":{"client":[379,379],"moderationOpts":[380,380]},"supers":[]},"useSearchPostsV2Query":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Search for a topic \u00b7 sequence"]],"code":"export function useSearchPostsV2Query({\n  query,\n  sort,\n  enabled,\n  filters,\n}: {\n  query: string\n  sort?: 'top' | 'latest'\n  enabled?: boolean\n  filters?: SearchFilters\n}) {\n  const client = useAppviewClient()\n  const moderationOpts = useModerationOpts()\n  const selectArgs = useMemo(\n    () => ({\n      isSearchingSpecificUser:\n        /from:(\\w+)/.test(query) || !!filters?.author || filters?.from === 'me',\n      moderationOpts,\n    }),\n    [query, filters?.author, filters?.from, moderationOpts],\n  )\n  const lastRun = useRef<{\n    data: InfiniteData<app.bsky.feed.searchPostsV2.$OutputBody>\n    args: typeof selectArgs\n    result: InfiniteData<app.bsky.feed.searchPostsV2.$OutputBody>\n  } | null>(null)\n\n  return useInfiniteQuery<\n    app.bsky.feed.searchPostsV2.$OutputBody,\n    Error,\n    InfiniteData<app.bsky.feed.searchPostsV2.$OutputBody>,\n    QueryKey,\n    string | undefined\n  >({\n    queryKey: searchPostsV2QueryKey({query, sort, filters}),\n    queryFn: async ({pageParam}) => {\n      /*\n       * Operators embedded in the query string (e.g. for back-compat links) are\n       * merged with the explicit structured filters from the advanced search\n       * dialog; see buildSearchPostsV2Filters for how the two sources combine.\n       */\n      const {q, ...embedded} = extractSearchPostsParams(query)\n      /*\n       * The generated params brand format-constrained strings (uri,\n       * at-identifier, language) as template-literal types. The builder emits\n       * plain strings parsed from user input, which are runtime-identical, so\n       * the brand is asserted rather than re-validated here.\n       */\n      const builtFilters = buildSearchPostsV2Filters(\n        embedded,\n        filters,\n      ) as app.bsky.feed.searchPostsV2.$Params\n      const finalQuery = appendFromMe(q, filters?.from === 'me')\n      return await client.call(app.bsky.feed.searchPostsV2, {\n        ...builtFilters,\n        query: finalQuery,\n        limit: 25,\n        cursor: pageParam,\n        /*\n         * v2 calls the recency sort 'recent'; the rest of the app still uses\n         * the v1 'latest' label.\n         */\n        sort: sort === 'latest' ? 'recent' : sort,\n        allTime: true,\n      })\n    },\n    initialPageParam: undefined,\n    getNextPageParam: lastPage => lastPage.cursor,\n    enabled: enabled ?? !!moderationOpts,\n    select: useCallback(\n      (data: InfiniteData<app.bsky.feed.searchPostsV2.$OutputBody>) => {\n        const {moderationOpts, isSearchingSpecificUser} = selectArgs\n\n        /*\n         * If a user applies the `from:<user>` filter, don't apply any\n         * moderation. Note that if we add any more filtering logic below, we\n         * may need to adjust this.\n         */\n        if (isSearchingSpecificUser) {\n          return data\n        }\n\n        /*\n         * Keep track of the last run and whether we can reuse some already\n         * selected pages from there.\n         */\n        let reusedPages = []\n        if (lastRun.current) {\n          const {\n            data: lastData,\n            args: lastArgs,\n            result: lastResult,\n          } = lastRun.current\n          let canReuse = true\n          for (let key in selectArgs) {\n            if (selectArgs.hasOwnProperty(key)) {\n              if (\n                (selectArgs as Record<string, unknown>)[key] !==\n                (lastArgs as Record<string, unknown>)[key]\n              ) {\n                // Can't do reuse anything if any input has changed.\n                canReuse = false\n                break\n              }\n            }\n          }\n          if (canReuse) {\n            for (let i = 0; i < data.pages.length; i++) {\n              if (data.pages[i] && lastData.pages[i] === data.pages[i]) {\n                reusedPages.push(lastResult.pages[i])\n                continue\n              }\n              // Stop as soon as pages stop matching up.\n              break\n            }\n          }\n        }\n\n        const result = {\n          ...data,\n          pages: [\n            ...reusedPages,\n            ...data.pages.slice(reusedPages.length).map(page => {\n              return {\n                ...page,\n                posts: page.posts.filter(post => {\n                  const mod = moderatePost(post, moderationOpts!)\n                  return !mod.ui('contentList').filter\n                }),\n              }\n            }),\n          ],\n        }\n\n        lastRun.current = {data, result, args: selectArgs}\n\n        return result\n      },\n      [selectArgs],\n    ),\n  })\n}","file":"src/state/queries/search-posts-v2.ts","kind":"hook","line":37,"members":{"client":[48,48],"lastRun":[58,62],"moderationOpts":[49,49],"selectArgs":[50,57]},"supers":[]}},"sourceUrl":"https://github.com/bluesky-social/social-app/blob/f7399a645c08dcf5d15f8cac64417ac73fe6ddf9/"};
